/// <summary>
/// Extension class for table <c>GUPItemBasePrice</c>
/// </summary>
[ExtensionOf(tableStr(GUPItemBasePrice))]
public final class METGUPItemBasePrice_Extension
{
}

Method.Source:
    /// <summary>
    /// Initialise table buffer from GUPItemBasePriceSim table buffer 
    /// </summary>
    /// <param name = "_itemBasePriceSim">GUPItemBasePriceSim buffer</param>
    public void initFromGUPItemBasePriceSim(GUPItemBasePriceSim _itemBasePriceSim)
    {
        next initFromGUPItemBasePriceSim(_itemBasePriceSim);

        this.METVendClaimEnabled = _itemBasePriceSim.METVendClaimEnabled;
    }

    /// <summary>
    /// CB434, Initialise and create InventItemPrice based on the GUPItemBasePriceRecord
    /// </summary>
    public void inventItemPriceCreation()
    {
        InventItemPriceSim          inventItemPriceSim;
        GUPParameters               gupParameters = GUPParameters::find();

        inventItemPriceSim.clear();
        inventItemPriceSim.ItemId              = this.ItemId;
        //inventItemPrice.initFromInventTableModule(InventTableModule::find(this.ItemId, ModuleInventPurchSales::Invent));
        inventItemPriceSim.VersionId           = gupParameters.METCostingVersionId;
        //inventItemPrice.initFromCostingVersion();
        inventItemPriceSim.InventDimId         = InventTable::priceInventDimId(this.ItemId, this.InventDimId);
        inventItemPriceSim.PriceType           = CostingVersionPriceType::Cost;
        inventItemPriceSim.PriceQty            = 1;
        inventItemPriceSim.PriceUnit           = 1;
        inventItemPriceSim.Markup              = 0;
        inventItemPriceSim.UnitID              = this.UnitId;
        inventItemPriceSim.Price               = this.Price;
        inventItemPriceSim.PriceCalcId         = this.PriceCalcId;
        inventItemPriceSim.FromDate      = this.FromDate;
        
        if(inventItemPriceSim.validateWrite())
        {
            inventItemPriceSim.insert();
            InventItemPriceActivationJob::activateInventItemPriceSimExt(inventItemPriceSim);
        }
    }

    /// <summary>
    /// Method to identify and retreivce a <c>GUPItemBasePrice</c> table buffer.
    /// </summary>
    /// <param name = "_itemId">Unique Item Id</param>
    /// <param name = "_priceType">Price type of the record to be  fetched</param>
    /// <param name = "_inventDimId">Unique inventory dimension Id</param>
    /// <param name = "_date">Date value to fitler and fetch record from this table</param>
    /// <param name = "_accountRelation"> Pricing associated with vendor account</param>
    /// <param name = "_activationDate">Date as when the pricing was activated</param>
    /// <param name = "_newSiteId">Unique inventory site Id</param>
    /// <param name = "_forUpdate">Boolean True, paramter to determine the update of record else false</param>
    /// <returns>Returns <c>GUPItemBasePrice</c> table buffer.</returns>
    public static GUPItemBasePrice metFindCurrentBasePriceForICReplenishTransferPurchLines(
        ItemId                  _itemId,
        GUPBasePriceType        _priceType,
        InventDimId             _inventDimId,
        date                    _date = dateNull(),
        GUPVendPriceRelation    _accountRelation = '',
        UnitOfMeasureSymbol     _unitId = '',
        TransDate               _activationDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
        InventSiteId            _newSiteId      = '',
        boolean                 _forUpdate      = false
        )
    {
        GUPItemBasePrice     itemBasePrice;

        if (_itemId
            && InventDim::find(_inventDimId).isOwnerCurrentLegalEntity())
        {
            InventTable inventTable         = InventTable::find(_itemId);
            InventDim inventDimCriteria     = GUPItemBasePrice::initInventDimCriteria(inventTable, _inventDimId);
            inventDimCriteria.InventSiteId  = InventItemPrice::changeSiteId(inventDimCriteria.InventSiteId, _newSiteId);
            itemBasePrice.selectForUpdate(_forUpdate);

            InventDim inventDim = InventDim::findDim(inventDimCriteria);

            select firstonly itemBasePrice
                order by ActivationDate desc, BasePriceCreatedDateTime desc
                where itemBasePrice.ItemId         == _itemId
                    && itemBasePrice.PriceType      == _priceType
                    && itemBasePrice.ActivationDate <= _activationDate
                    && itemBasePrice.InventDimId    == inventDim.inventDimId
                    && (_date == dateNull() || (itemBasePrice.FromDate == dateNull() || itemBasePrice.FromDate <= _date))
                    && (_date == dateNull() || (itemBasePrice.ToDate == dateNull() || itemBasePrice.ToDate >= _date))
                    && (_accountRelation == '' || (itemBasePrice.AccountRelation == '' || itemBasePrice.AccountRelation == _accountRelation))
                    && (_unitId == '' || (itemBasePrice.UnitId == '' || itemBasePrice.UnitId == _unitId));

        }

        return itemBasePrice;
    }
